<script setup lang="ts">
import { computed, onBeforeUnmount, ref } from "vue";
import { auth, request, saveTokens } from "../../api";

type LoginMethod = "password" | "code";
type SocialProvider = "wechat" | "qq";
type QrState = "loading" | "pending" | "config" | "expired" | "error";
interface OAuthStart {configured:boolean;session_id?:string;authorization_url?:string;qr_image_url?:string;callback_url?:string;message?:string}
const mode = ref<"login" | "register">("login"), method = ref<LoginMethod>("password");
const phone = ref(""), code = ref(""), password = ref(""), nickname = ref("");
const agreed = ref(true), showPassword = ref(false), loading = ref(false), seconds = ref(0);
const socialProvider = ref<SocialProvider|null>(null), qrState = ref<QrState>("loading"), qrImage = ref(""), qrSession = ref(""), qrMessage = ref(""), callbackUrl = ref(""), authorizationUrl = ref("");
let timer: ReturnType<typeof setInterval> | undefined, qrTimer: ReturnType<typeof setInterval> | undefined;
const isRegister = computed(() => mode.value === "register");
const title = computed(() => isRegister.value ? "创建你们的恋爱日记" : "欢迎回到我们的故事");
const submitText = computed(() => loading.value ? "正在轻轻打开…" : isRegister.value ? "注册并开启日记" : method.value === "code" ? "验证并登录" : "登录");
const cleanPhone = () => phone.value.replace(/\s/g, "");
function validPhone(){if(!/^1\d{10}$/.test(cleanPhone())){uni.showToast({title:"请输入正确的 11 位手机号",icon:"none"});return false}return true}
function switchMode(next:"login"|"register"){mode.value=next;method.value=next==="register"?"code":"password";code.value="";password.value=""}
async function sendCode(){
  if(seconds.value||!validPhone())return;
  try{
    const result=await request<{message:string;dev_code?:string}>("/api/v1/auth/code","POST",{phone:cleanPhone()});
    seconds.value=60;timer=setInterval(()=>{seconds.value-=1;if(seconds.value<=0&&timer)clearInterval(timer)},1000);
    uni.showToast({title:result.dev_code?`开发验证码：${result.dev_code}`:result.message,icon:"none",duration:result.dev_code?5000:2000});
  }catch(error){uni.showToast({title:(error as Error).message,icon:"none"})}
}
async function submit(){
  if(!validPhone())return;
  if(!agreed.value){uni.showToast({title:"请先同意用户协议与隐私政策",icon:"none"});return}
  if(isRegister.value&&!nickname.value.trim()){uni.showToast({title:"给自己取一个昵称吧",icon:"none"});return}
  if((isRegister.value||method.value==="code")&&!/^\d{6}$/.test(code.value)){uni.showToast({title:"请输入 6 位验证码",icon:"none"});return}
  if((isRegister.value||method.value==="password")&&password.value.length<6){uni.showToast({title:"密码至少需要 6 位",icon:"none"});return}
  loading.value=true;
  try{
    if(isRegister.value)await auth("phone/register",{phone:cleanPhone(),code:code.value,password:password.value,nickname:nickname.value.trim()});
    else if(method.value==="code")await auth("phone/code-login",{phone:cleanPhone(),code:code.value});
    else await auth("phone/login",{phone:cleanPhone(),password:password.value});
    uni.redirectTo({url:"/pages/space/space"});
  }catch(error){uni.showToast({title:(error as Error).message,icon:"none"})}finally{loading.value=false}
}
const socialName = computed(()=>socialProvider.value==="qq"?"QQ":"微信");
function stopQrPolling(){if(qrTimer){clearInterval(qrTimer);qrTimer=undefined}}
function closeSocial(){stopQrPolling();socialProvider.value=null;qrImage.value="";qrSession.value="";authorizationUrl.value=""}
async function pollQr(){
  if(!qrSession.value)return;
  try{
    const result=await request<{status:string;message?:string;access_token?:string;refresh_token?:string}>(`/api/v1/auth/oauth/session/${qrSession.value}`);
    if(result.status==="authorized"&&result.access_token&&result.refresh_token){saveTokens(result.access_token,result.refresh_token);closeSocial();uni.showToast({title:"登录成功",icon:"success"});setTimeout(()=>uni.redirectTo({url:"/pages/space/space"}),350)}
    else if(result.status==="expired"||result.status==="error"){stopQrPolling();qrState.value=result.status;qrMessage.value=result.message||"登录未完成，请重试"}
  }catch(error){stopQrPolling();qrState.value="error";qrMessage.value=(error as Error).message}
}
async function startQr(provider:SocialProvider){
  if(!agreed.value){uni.showToast({title:"请先同意用户协议与隐私政策",icon:"none"});return}
  stopQrPolling();socialProvider.value=provider;qrState.value="loading";qrImage.value="";qrSession.value="";qrMessage.value="";callbackUrl.value="";authorizationUrl.value="";
  try{
    const result=await request<OAuthStart>(`/api/v1/auth/oauth/${provider}/start`,"POST",{});
    if(!result.configured){qrState.value="config";qrMessage.value=result.message||"扫码登录尚未配置";callbackUrl.value=result.callback_url||"";return}
    qrSession.value=result.session_id||"";qrImage.value=result.qr_image_url||"";authorizationUrl.value=result.authorization_url||"";qrState.value="pending";
    qrTimer=setInterval(pollQr,1600);
  }catch(error){qrState.value="error";qrMessage.value=(error as Error).message}
}
function socialLogin(provider:SocialProvider){
  // #ifdef MP-WEIXIN
  if(provider==="wechat"){uni.login({success:async result=>{try{await auth("wechat",{code:result.code});uni.redirectTo({url:"/pages/space/space"})}catch(error){uni.showToast({title:(error as Error).message,icon:"none"})}}});return}
  // #endif
  startQr(provider);
}
function refreshQr(){if(socialProvider.value)startQr(socialProvider.value)}
function openProviderLogin(){
  if(!authorizationUrl.value)return;
  // #ifdef H5
  window.open(authorizationUrl.value,"_blank","noopener,noreferrer");
  // #endif
}
onBeforeUnmount(()=>{if(timer)clearInterval(timer);stopQrPolling()});
</script>

<template>
  <view class="page">
    <view class="glow glow-one"/><view class="glow glow-two"/>
    <view class="floating-heart heart-one">♥</view><view class="floating-heart heart-two">♥</view><view class="floating-heart heart-three">♥</view>
    <view class="brand"><view class="brand-mark">♥</view><text class="brand-name">恋爱日记</text></view>
    <view class="illustration photo-illustration" aria-label="一二和布布牵手的情侣动态头像">
      <view class="portrait-halo"/><view class="portrait-ring ring-one"/><view class="portrait-ring ring-two"/>
      <image class="couple-photo" src="/static/couple-yi-er-bu-bu.png" mode="aspectFit"/>
      <view class="photo-heart photo-heart-one">♥</view><view class="photo-heart photo-heart-two">♥</view>
      <view class="photo-sparkle photo-sparkle-one">✦</view><view class="photo-sparkle photo-sparkle-two">✧</view>
      <view class="couple-caption"><text class="name">一二</text><text class="tiny-heart">♥</text><text class="name">布布</text></view>
    </view>
    <view class="welcome"><text class="eyebrow">TWO HEARTS · ONE STORY</text><text class="headline">{{title}}</text><text class="subtitle">把每一个普通日子，都变成值得珍藏的纪念</text></view>
    <view class="card">
      <view class="mode-switch"><view :class="['mode-item',{active:mode==='login'}]" @click="switchMode('login')">登录</view><view :class="['mode-item',{active:mode==='register'}]" @click="switchMode('register')">注册</view></view>
      <view v-if="!isRegister" class="method-tabs"><text :class="{active:method==='password'}" @click="method='password'">密码登录</text><text :class="{active:method==='code'}" @click="method='code'">验证码登录</text></view>
      <view v-if="isRegister" class="field"><text class="field-icon">☺</text><input v-model="nickname" maxlength="20" placeholder="你的昵称" placeholder-class="placeholder"/></view>
      <view class="field"><text class="field-icon">♧</text><text class="phone-prefix">+86</text><view class="divider"/><input v-model="phone" type="number" maxlength="11" placeholder="请输入手机号" placeholder-class="placeholder"/></view>
      <view v-if="isRegister||method==='code'" class="field"><text class="field-icon">✉</text><input v-model="code" type="number" maxlength="6" placeholder="6 位短信验证码" placeholder-class="placeholder"/><button class="code-button" :disabled="seconds>0" @click="sendCode">{{seconds?`${seconds}s`:'获取验证码'}}</button></view>
      <view v-if="isRegister||method==='password'" class="field"><text class="field-icon">⌁</text><input v-model="password" :password="!showPassword" maxlength="32" :placeholder="isRegister?'设置密码（至少 6 位）':'请输入密码'" placeholder-class="placeholder"/><text class="eye-button" @click="showPassword=!showPassword">{{showPassword?'◉':'◎'}}</text></view>
      <view v-if="!isRegister&&method==='password'" class="assist-row"><text class="remember"><text class="check-small">✓</text> 记住我</text><text class="forgot" @click="method='code'">忘记密码？</text></view>
      <button class="primary" :disabled="loading" @click="submit"><text>{{submitText}}</text><text class="arrow">→</text></button>
      <view class="agreement" @click="agreed=!agreed"><view :class="['checkbox',{checked:agreed}]">{{agreed?'✓':''}}</view><text>我已阅读并同意 <text class="link">《用户协议》</text> 和 <text class="link">《隐私政策》</text></text></view>
      <view class="or"><view/><text>其他登录方式</text><view/></view>
      <view class="social-logins">
        <button class="social-button wechat-button" @click="socialLogin('wechat')"><view class="social-icon wechat-logo"><text>••</text></view><text>微信登录</text><text class="scan-hint">扫码</text></button>
        <button class="social-button qq-button" @click="socialLogin('qq')"><view class="social-icon qq-logo">QQ</view><text>QQ 登录</text><text class="scan-hint">扫码</text></button>
      </view>
    </view>
    <view class="footer"><text>愿每一次记录，都让爱更有迹可循</text><text class="footer-heart">♥</text></view>
    <view v-if="socialProvider" class="modal-mask" @click="closeSocial"><view class="oauth-modal" @click.stop>
      <text class="modal-close" @click="closeSocial">×</text>
      <view class="oauth-brand"><view class="brand-mark small">♥</view><text>恋爱日记</text></view>
      <view class="oauth-tabs"><view :class="{active:socialProvider==='wechat'}" @click="startQr('wechat')">微信登录</view><view :class="{active:socialProvider==='qq'}" @click="startQr('qq')">QQ 登录</view></view>
      <view class="oauth-content">
        <text class="modal-title">{{socialName}}扫码登录</text>
        <view v-if="qrState==='loading'" class="qr-placeholder"><view class="loading-heart">♥</view><text>正在生成安全二维码…</text></view>
        <view v-else-if="qrState==='pending'" class="qr-area"><view class="qr-shell real-qr"><image :src="qrImage" mode="aspectFit"/><view :class="['qr-provider',socialProvider]"><text>{{socialProvider==='wechat'?'••':'QQ'}}</text></view></view><text class="modal-tip">请使用{{socialName}}扫一扫登录</text><text class="modal-note">二维码 5 分钟内有效 · 扫码后本页将自动登录</text><button class="provider-web-login" @click="openProviderLogin">无法扫码？在腾讯官方页面授权 →</button></view>
        <view v-else-if="qrState==='config'" class="config-panel"><view :class="['provider-badge',socialProvider]">{{socialProvider==='wechat'?'微信':'QQ'}}</view><text class="config-title">{{qrMessage}}</text><text class="config-step">在后端 .env 中填写 {{socialProvider==='wechat'?'WECHAT_WEB_APPID / WECHAT_WEB_SECRET':'QQ_APPID / QQ_SECRET'}}</text><text class="callback-label">平台回调地址</text><text class="callback-url" selectable>{{callbackUrl}}</text></view>
        <view v-else class="qr-placeholder"><text class="state-icon">!</text><text>{{qrMessage}}</text><button class="refresh-qr" @click="refreshQr">刷新二维码</button></view>
      </view>
      <view class="oauth-safe"><text>◈</text><text>安全登录 · 不会保存你的第三方账号密码</text></view>
    </view></view>
  </view>
</template>

<style scoped lang="scss">
